CREATE TABLE public.products (
  id serial PRIMARY KEY, slug text NOT NULL UNIQUE, name text NOT NULL, subtitle text, description text NOT NULL,
  price numeric(10,2) NOT NULL, compare_at_price numeric(10,2), category text NOT NULL, fit text NOT NULL, material text NOT NULL,
  care_instructions text, details text, images text NOT NULL, colors text, sizes text NOT NULL,
  is_featured boolean DEFAULT false, is_new boolean DEFAULT false, is_bestseller boolean DEFAULT false, in_stock boolean DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.reviews (
  id serial PRIMARY KEY, product_id integer NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  author_name text NOT NULL, rating integer NOT NULL, title text NOT NULL, comment text NOT NULL, fit_feedback text,
  verified_purchase boolean DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.orders (
  id serial PRIMARY KEY, order_number text NOT NULL UNIQUE, customer_name text NOT NULL, customer_email text NOT NULL, customer_phone text,
  shipping_address text NOT NULL, shipping_city text NOT NULL, shipping_postal_code text NOT NULL, shipping_country text NOT NULL,
  shipping_method text NOT NULL DEFAULT 'Standard Courier', shipping_cost numeric(10,2) NOT NULL DEFAULT 0, subtotal numeric(10,2) NOT NULL,
  discount numeric(10,2) NOT NULL DEFAULT 0, tax numeric(10,2) NOT NULL DEFAULT 0, total numeric(10,2) NOT NULL, promo_code text,
  status text NOT NULL DEFAULT 'Processing', payment_status text NOT NULL DEFAULT 'Paid', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.order_items (
  id serial PRIMARY KEY, order_id integer NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  product_id integer REFERENCES public.products(id) ON DELETE SET NULL, product_name text NOT NULL, product_slug text NOT NULL,
  product_image text NOT NULL, size text NOT NULL, color text NOT NULL, price numeric(10,2) NOT NULL, quantity integer NOT NULL DEFAULT 1);
CREATE TABLE public.newsletter (id serial PRIMARY KEY, email text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.products, public.reviews, public.orders, public.order_items, public.newsletter TO service_role;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.newsletter ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.reset_store()
RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$
  TRUNCATE TABLE public.order_items, public.orders, public.reviews, public.products RESTART IDENTITY CASCADE;
$$;
REVOKE ALL ON FUNCTION public.reset_store() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.reset_store() TO service_role;

INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (1,'the-grandview-oxford-shirt','The Grandview Oxford Shirt','Double-twisted 120/2 yarn woven by Albini, Bergamo','The archetype of classic menswear. Cut from slow-woven 120/2 double-twisted Egyptian cotton that softens with every wash while retaining a crisp architectural roll at the button-down collar. Finished with authentic Australian mother-of-pearl buttons and 22-stitch-per-inch lockstitch seams.','135.00','165.00','Oxford & Formal','Tailored Fit','100% Giza 87 Egyptian Organic Cotton','Machine wash cold 30°C. Hang dry. Medium iron or steam.','["Woven in Bergamo by Albini 1876","Natural Australian mother-of-pearl Troca buttons","Gentle 3.5\" collar roll with floating interlining","Pre-washed for zero shrinkage","Single-needle French seams throughout"]','["/products/classic-white-oxford.jpg","https://images.pexels.com/photos/37218483/pexels-photo-37218483.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/32179336/pexels-photo-32179336.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800"]','[{"name":"Crisp White","hex":"#FFFFFF"},{"name":"Sky Chambray","hex":"#BFD7EA"},{"name":"Pale Pink","hex":"#F7E1D7"}]','[{"size":"S","stock":12},{"size":"M","stock":24},{"size":"L","stock":18},{"size":"XL","stock":10},{"size":"XXL","stock":4}]',true,false,true,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (2,'the-amalfi-camp-collar-resort-shirt','The Amalfi Camp Collar Resort Shirt','Garment-dyed linen with signature open Cuban collar','An effortless essential for warmer climates and relaxed evenings. Spun from long-staple French Normandy flax and enzyme-washed for a buttery, lived-in handfeel. Features a relaxed silhouette, side split vents, and an open camp collar that frames the collarbone with ease.','145.00','175.00','Linen & Resort','Relaxed Fit','100% French Normandy Washed Linen (175 gsm)','Gentle machine wash cold. Hang dry in shade. Light steam.','["Grade-A Normandy flax fibers","Enzyme-washed for effortless drape","Deep chest patch pocket with bar-tack reinforcement","Straight hem engineered for untucked wear","Reinforced split side vents"]','["/products/washed-olive-linen.jpg","https://images.pexels.com/photos/18031036/pexels-photo-18031036.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/27584193/pexels-photo-27584193.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800"]','[{"name":"Olive Earth","hex":"#556B2F"},{"name":"Sand Taupe","hex":"#D2B48C"},{"name":"Warm Terracotta","hex":"#C86446"}]','[{"size":"S","stock":8},{"size":"M","stock":19},{"size":"L","stock":15},{"size":"XL","stock":7},{"size":"XXL","stock":3}]',true,true,true,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (3,'the-oslo-heavy-wool-overshirt','The Oslo Heavy Wool Overshirt','380 gsm dense outerwear shirt with custom horn buttons','Engineered to bridge the transition between shirt and outerwear jacket. Cut from a dense 380 gsm recycled wool and cashmere blend milled in Prato, Italy. Twin utilitarian flap pockets, satin sleeve lining for frictionless layering over knitwear, and genuine buffalo horn buttons.','215.00','250.00','Overshirts','Classic Fit','70% Recycled Italian Wool, 25% Polyamide, 5% Cashmere','Specialist dry clean only. Brush lightly to maintain nap.','["380 GSM heavyweight Italian wool blend","Cupro sleeve lining for smooth layering","Twin flap-and-button utility chest pockets","Matte horn buttons with Henro subtle engraving","Double-stitched stress points"]','["/products/charcoal-overshirt.jpg","https://images.pexels.com/photos/37556024/pexels-photo-37556024.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/8972551/pexels-photo-8972551.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800"]','[{"name":"Charcoal Melange","hex":"#2F353B"},{"name":"Midnight Navy","hex":"#1A233A"},{"name":"Camel","hex":"#A88350"}]','[{"size":"S","stock":6},{"size":"M","stock":14},{"size":"L","stock":12},{"size":"XL","stock":5},{"size":"XXL","stock":2}]',true,true,false,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (4,'the-milano-pinpoint-poplin-dress-shirt','The Milano Pinpoint Poplin Dress Shirt','Semi-spread collar with removable brass collar stays','Designed for razor-sharp tailoring under bespoke suiting. Crafted from superfine 140/2 two-ply Supima cotton with a silky pinpoint weave that glides beneath a jacket sleeve. Clean French placket, mitred two-button cuffs, and sculpted back darts for an elegant v-taper.','155.00','180.00','Oxford & Formal','Tailored Fit','100% Two-Ply Supima Cotton (140/2)','Machine wash delicate 30°C. Press while damp for pristine luster.','["140/2 Supima extra-long staple yarn","Semi-spread collar with removable solid brass stays","Clean French placket with seamless front","Mitred barrel cuffs with twin mother-of-pearl buttons","Curved hem tailored to stay tucked all day"]','["/products/sky-blue-poplin.jpg","https://images.pexels.com/photos/38272126/pexels-photo-38272126.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/38285770/pexels-photo-38285770.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800"]','[{"name":"Sky Pinpoint","hex":"#C5D9E8"},{"name":"Pure White","hex":"#FFFFFF"},{"name":"French Blue","hex":"#4682B4"}]','[{"size":"S","stock":10},{"size":"M","stock":20},{"size":"L","stock":16},{"size":"XL","stock":8},{"size":"XXL","stock":3}]',true,false,true,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (5,'the-kyoto-indigo-selvedge-chambray','The Kyoto Indigo Selvedge Chambray','Woven in Kojima, Okayama with selvedge side gussets','Woven on vintage 1960s Toyoda shuttle looms in Okayama, this 6.5 oz chambray showcases subtle neps and slubs unique to slow-speed heritage weaving. Finished with selvedge side gussets, run-off chainstitch detailing, and cats-eye urea buttons that age with dignity.','165.00','195.00','Casual Poplin','Classic Fit','100% Japanese Shuttle-Loomed Cotton (6.5 oz)','Wash cold inside-out with like colors. Air dry. Will develop unique fade.','["Woven in Okayama on vintage shuttle looms","Selvedge detailing at hem gusset and inner placket","Natural rope-dyed indigo develops bespoke patina","Double-needle chainstitch construction","Vintage cat''s eye resin buttons"]','["https://images.pexels.com/photos/17076311/pexels-photo-17076311.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/5924462/pexels-photo-5924462.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/38285771/pexels-photo-38285771.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800"]','[{"name":"Rope Indigo","hex":"#2B4162"},{"name":"Bleached Wash","hex":"#7798AB"}]','[{"size":"S","stock":5},{"size":"M","stock":15},{"size":"L","stock":12},{"size":"XL","stock":6}]',false,true,false,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (6,'the-st-moritz-cashmere-cotton-knit-shirt','The St. Moritz Cashmere-Cotton Knit Shirt','14-gauge fully-fashioned fine knit with full button closure','The luxurious intersection of a tailored button-down and a cloud-soft knit sweater. Knitted on Japanese 14-gauge machines from an intimate blend of combed cotton and Mongolian cashmere. Features ribbed cuffs and hem, knit polo collar, and mother-of-pearl buttons.','185.00','220.00','Knit & Polo','Tailored Fit','85% Combed Long-Staple Cotton, 15% Grade-A Mongolian Cashmere','Hand wash cold or gentle wool cycle in laundry bag. Lay flat to dry.','["14-gauge fully-fashioned seamless knit","Grade-A Mongolian cashmere blend","Ribbed collar that holds its structure without rolling","Full button placket with grosgrain backing","Naturally temperature regulating"]','["https://images.pexels.com/photos/8159360/pexels-photo-8159360.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/11749794/pexels-photo-11749794.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","/products/washed-olive-linen.jpg"]','[{"name":"Oatmeal Heather","hex":"#D6CFC7"},{"name":"Espresso","hex":"#3B2F2F"},{"name":"Slate Grey","hex":"#708090"}]','[{"size":"S","stock":7},{"size":"M","stock":18},{"size":"L","stock":14},{"size":"XL","stock":6}]',true,true,true,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (7,'the-riviera-striped-voile-linen','The Riviera Striped Voile Linen','Breezy yarn-dyed awning stripe with convertible collar','A nod to 1960s French Riviera leisure. The airy open weave combines Belgian linen for breathability with organic cotton for low-crease softness. Finished with warm terracotta candy stripes, genuine corozo nut buttons, and a convertible notch collar.','140.00','165.00','Linen & Resort','Relaxed Fit','55% Belgian Linen, 45% Organic Cotton','Machine wash cold delicate. Hang to dry. Iron on linen setting.','["Yarn-dyed Mediterranean awning stripe","Lightweight 135 gsm open voile weave","Natural vegetable corozo nut buttons","Straight back yoke with twin side pleats","Pre-shrunk enzyme wash"]','["https://images.pexels.com/photos/12871421/pexels-photo-12871421.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/1850172/pexels-photo-1850172.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/26588136/pexels-photo-26588136.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800"]','[{"name":"Terracotta Stripe","hex":"#CD5C5C"},{"name":"Navy Awning","hex":"#23395B"}]','[{"size":"S","stock":8},{"size":"M","stock":16},{"size":"L","stock":12},{"size":"XL","stock":5}]',false,false,true,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (8,'the-minimalist-mandarin-collar-poplin','The Minimalist Mandarin Collar Poplin','Architectural clean collar with concealed button placket','A study in restrained minimalism. Engineered with a clean 2.8cm band collar and a concealed front placket that hides the buttons for an uninterrupted, architectural line. Cut from mercerized Egyptian cotton with a deep, permanent jet-black luster that will not fade.','145.00','170.00','Casual Poplin','Tailored Fit','100% Mercerized Egyptian Mako Cotton','Machine wash 30°C gentle. Avoid bleach. Steam to finish.','["Mercerized Mako cotton with deep color lock","Architectural 2.8cm standing band collar","Concealed front placket for clean aesthetic","Back shoulder tucks for ergonomic reach","Adjustable two-button barrel cuffs"]','["https://images.pexels.com/photos/37218519/pexels-photo-37218519.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/3754215/pexels-photo-3754215.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/39108731/pexels-photo-39108731.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800"]','[{"name":"Pitch Black","hex":"#111111"},{"name":"Concrete Grey","hex":"#8A8D8F"}]','[{"size":"S","stock":6},{"size":"M","stock":14},{"size":"L","stock":10},{"size":"XL","stock":4}]',false,false,false,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (9,'the-hudson-heavy-cotton-flannel-overshirt','The Hudson Heavy Cotton Flannel Overshirt','Custom yarn-dyed heritage twill with micro-brushed finish','Built for crisp autumn breezes and mountain escapes. Woven from 310 gsm heavyweight organic cotton twill that is double-brushed on both exterior and interior faces for unmatched tactile softness. Finished with dual chest pockets and reinforced elbow patches.','175.00','210.00','Overshirts','Oversized Fit','100% Double-Brushed Organic Cotton (310 gsm)','Machine wash warm with like colors. Tumble dry low or line dry.','["310 GSM heavyweight twill weave","Double-brushed interior and exterior for plush handfeel","Reinforced elbow articulation panels","Matte tortoise resin buttons","Boxy relaxed silhouette designed for layering"]','["https://images.pexels.com/photos/29123215/pexels-photo-29123215.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/36395697/pexels-photo-36395697.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/17615753/pexels-photo-17615753.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800"]','[{"name":"Cedar Plaid","hex":"#7E523A"},{"name":"Forest Olive","hex":"#3D4F3E"}]','[{"size":"S","stock":9},{"size":"M","stock":17},{"size":"L","stock":15},{"size":"XL","stock":8}]',false,false,true,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (10,'the-silk-modal-evening-shirt','The Silk-Modal Evening Shirt','Liquid drape with subtle sheen and French cuffs','Designed for black-tie gatherings and sunset celebrations. The blend of pure Mulberry silk and high-twist Austrian modal creates a liquid-like drape that catches the light with understated luxury. Finished with subtle convertible cuffs that can accept cufflinks or button closed.','195.00','235.00','Knit & Polo','Relaxed Fit','30% Mulberry Silk, 70% Austrian TENCEL Modal','Dry clean recommended or gentle silk hand wash in cold water.','["Grade 6A Mulberry silk blended with Austrian Modal","Ultra-soft fluid drape with satin sheen","Convertible dual cuffs (button or cufflinks)","Curved hem with reinforced side gussets","Gentle dry-clean or silk hand wash"]','["https://images.pexels.com/photos/8070558/pexels-photo-8070558.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/5149729/pexels-photo-5149729.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","/products/classic-white-oxford.jpg"]','[{"name":"Champagne Ivory","hex":"#EBE3D5"},{"name":"Nocturne Black","hex":"#1C1C1E"}]','[{"size":"S","stock":4},{"size":"M","stock":10},{"size":"L","stock":8},{"size":"XL","stock":3}]',false,true,false,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (11,'the-modernist-seersucker-short-sleeve','The Modernist Seersucker Short-Sleeve','Micro-texture crinkle weave engineered for extreme heat','Engineered specifically for stifling summer days. The puckered seersucker weave lifts the fabric away from the skin, maximizing airflow and natural convection. Completely iron-free and naturally wrinkle-resistant with a clean Cuban revere collar.','130.00','150.00','Linen & Resort','Relaxed Fit','100% Organic Puckered Cotton Seersucker','Machine wash cold. Dries in minutes. No ironing necessary.','["Permanent natural puckered weave (100% iron-free)","Cuban camp collar with loop top closure","Square bottom hem with side slits","Mother-of-pearl buttons","Naturally lightweight 125 GSM"]','["https://images.pexels.com/photos/30710542/pexels-photo-30710542.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/18031039/pexels-photo-18031039.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","/products/washed-olive-linen.jpg"]','[{"name":"Sage Mist","hex":"#A3B899"},{"name":"Ice Blue","hex":"#D0E1FD"},{"name":"Bone White","hex":"#F3EFE0"}]','[{"size":"S","stock":11},{"size":"M","stock":22},{"size":"L","stock":17},{"size":"XL","stock":9}]',false,false,true,true);
INSERT INTO public.products (id,slug,name,subtitle,description,price,compare_at_price,category,fit,material,care_instructions,details,images,colors,sizes,is_featured,is_new,is_bestseller,in_stock) VALUES (12,'the-savile-row-double-cuff-tuxedo-shirt','The Savile Row Double-Cuff Tuxedo Shirt','Waffle bib front with removable stud buttons & French cuffs','Traditional formal wear executed with modern proportions. Woven from Sea Island cotton with a textured Marcella waffle bib and matching spread collar. Includes removable black onyx stud buttons that can easily be swapped for your own personal studs.','175.00','210.00','Oxford & Formal','Tailored Fit','100% Sea Island Cotton Marcella Pique','Professional laundering recommended. Starch collar lightly.','["Marcella pique bib front and fold-down collar","French double cuffs for custom cufflinks","Removable stud button strip included","Split yoke with hand-turned armholes","Tailored fit that contours without bunching"]','["https://images.pexels.com/photos/23914243/pexels-photo-23914243.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","https://images.pexels.com/photos/23879365/pexels-photo-23879365.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=1200&w=800","/products/sky-blue-poplin.jpg"]','[{"name":"Optical White","hex":"#FFFFFF"}]','[{"size":"S","stock":5},{"size":"M","stock":12},{"size":"L","stock":10},{"size":"XL","stock":4}]',false,false,false,true);
INSERT INTO public.reviews (id,product_id,author_name,rating,title,comment,fit_feedback,verified_purchase) VALUES (1,1,'Alexander Wright',5,'The collar roll alone is worth every dollar','I have owned oxfords from Drake''s and Brooks Brothers Golden Fleece, but HENRO''s 120/2 double-twisted Albini cotton is in a league of its own. The collar roll frames a tailored knit tie perfectly or stands effortlessly on its own under an unbuttoned blazer. True sartorial perfection.','True to size',true);
INSERT INTO public.reviews (id,product_id,author_name,rating,title,comment,fit_feedback,verified_purchase) VALUES (2,1,'Julian Vance, NYC',5,'Heirloom grade craftsmanship','The genuine Troca mother-of-pearl buttons are thick and tactile. After three washes, the cotton has that coveted buttery oxford patina while the collar and cuffs remain razor sharp.','True to size',true);
INSERT INTO public.reviews (id,product_id,author_name,rating,title,comment,fit_feedback,verified_purchase) VALUES (3,1,'Marcus Sterling',4,'Phenomenal shirt, slim through chest','Sublime drape and stitching. If you have broad lats or bench heavy, you may consider sizing up one notch, but for a modern tailored look it hugs without pulling.','Runs slightly small',true);
INSERT INTO public.reviews (id,product_id,author_name,rating,title,comment,fit_feedback,verified_purchase) VALUES (4,2,'Matteo Ricci',5,'Wore this throughout Southern Italy','The Normandy linen breathability is incredible. It doesn''t cling even in 34°C heat, and the olive hue has subtle depth that looks even better in natural daylight.','Relaxed drape',true);
INSERT INTO public.reviews (id,product_id,author_name,rating,title,comment,fit_feedback,verified_purchase) VALUES (5,2,'David Croft',5,'Unmatched drape, zero scratchiness','Usually 100% linen takes weeks of washing to stop being scratchy. This was soft right out of the signature black box. The Cuban collar sits flat and relaxed.','True to size',true);
INSERT INTO public.reviews (id,product_id,author_name,rating,title,comment,fit_feedback,verified_purchase) VALUES (6,3,'Henrik Lindqvist',5,'Architectural and warm without bulk','The 380gsm Prato wool has substantial heft. The cupro lining in the sleeves means it slips effortlessly over fine gauge cashmere rollnecks. Clean Scandinavian minimalism at its pinnacle.','True to size',true);
INSERT INTO public.reviews (id,product_id,author_name,rating,title,comment,fit_feedback,verified_purchase) VALUES (7,4,'Christian Dubois',5,'My new staple boardroom shirt','The French placket is clean and contemporary. The Supima 140/2 pinpoint has a soft, liquid-smooth sheen that commands presence in any room. The brass collar stays are a distinguished touch.','True to size',true);
INSERT INTO public.reviews (id,product_id,author_name,rating,title,comment,fit_feedback,verified_purchase) VALUES (8,6,'Oliver K.',5,'The softness is borderline addictive','The cashmere-cotton blend feels like a whisper on the skin. You can wear it buttoned up as an elegant shirt or unbuttoned over a white supima tank. Extraordinary piece.','True to size',true);
